-- FOODEX FOOD Van — Complete Egypt geographic tree
-- Generated for FOODEX geography_nodes/service_territories schema.
-- Source: Open Admin Data — Egypt Administrative Divisions
-- https://github.com/open-admin-data/egypt-administrative-divisions
-- License: CC-BY-4.0
--
-- Coverage:
--   1 country (Egypt)
--   27 governorates
--   365 administrative districts/markaz/qism
--   5,716 shiyakha/village/local-area records mapped to geography_nodes.type='area'
--   Active FOOD Van service territories: Egypt + every governorate + every district
--
-- Safe to re-run: geography nodes and territories are upserted by existing unique keys.
-- No existing non-Egypt geography is deleted.
-- This script intentionally does NOT invent polygon boundaries. territory_geometries stays untouched.

SET NAMES utf8mb4;
SET @OLD_SQL_SAFE_UPDATES := @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;

START TRANSACTION;

-- -------------------------------------------------------------------------
-- 1. Canonical Egypt country node
-- -------------------------------------------------------------------------
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
VALUES
(NULL,'country','EG','مصر','Egypt','EG',1,
 JSON_OBJECT(
   'source','Open Admin Data',
   'source_code','EG',
   'source_level','country',
   'food_van_level','country',
   'dataset','open-admin-data/egypt-administrative-divisions',
   'license','CC-BY-4.0'
 ),NOW(),NOW())
ON DUPLICATE KEY UPDATE
  id=LAST_INSERT_ID(id),
  parent_id=NULL,
  name_ar=VALUES(name_ar),
  name_en=VALUES(name_en),
  is_active=1,
  metadata=VALUES(metadata),
  updated_at=NOW();

SELECT id INTO @egypt_id
FROM geography_nodes
WHERE country_code='EG' AND type='country' AND code='EG'
LIMIT 1;

-- -------------------------------------------------------------------------
-- 2. Staging tree: governorate -> district/markaz/qism -> area/shiyakha/village
-- -------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_eg_food_van_geo;
CREATE TEMPORARY TABLE tmp_eg_food_van_geo (
  type varchar(32) NOT NULL,
  code varchar(96) NOT NULL,
  parent_type varchar(32) NOT NULL,
  parent_code varchar(96) NOT NULL,
  name_ar varchar(255) NOT NULL,
  name_en varchar(255) NOT NULL,
  PRIMARY KEY (type,code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

