-- -------------------------------------------------------------------------
-- 3. Governorates
-- -------------------------------------------------------------------------
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
SELECT
  @egypt_id,
  'governorate',
  s.code,
  s.name_ar,
  s.name_en,
  'EG',
  1,
  JSON_OBJECT(
    'source','Open Admin Data',
    'source_code',s.code,
    'source_level','governorate',
    'food_van_level','governorate',
    'dataset','open-admin-data/egypt-administrative-divisions',
    'license','CC-BY-4.0'
  ),
  NOW(),NOW()
FROM tmp_eg_food_van_geo s
WHERE s.type='governorate'
ON DUPLICATE KEY UPDATE
  parent_id=VALUES(parent_id),
  name_ar=VALUES(name_ar),
  name_en=VALUES(name_en),
  is_active=1,
  metadata=VALUES(metadata),
  updated_at=NOW();

-- -------------------------------------------------------------------------
-- 4. Districts / markaz / qism
-- Source dataset calls this level "district". Keep type='district' because
-- FOODEX already supports it and it works directly with service_territories.
-- -------------------------------------------------------------------------
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
SELECT
  p.id,
  'district',
  s.code,
  s.name_ar,
  s.name_en,
  'EG',
  1,
  JSON_OBJECT(
    'source','Open Admin Data',
    'source_code',s.code,
    'source_level','district',
    'food_van_level','district',
    'parent_source_code',s.parent_code,
    'dataset','open-admin-data/egypt-administrative-divisions',
    'license','CC-BY-4.0'
  ),
  NOW(),NOW()
FROM tmp_eg_food_van_geo s
JOIN geography_nodes p
  ON p.country_code='EG'
 AND p.type='governorate'
 AND p.code=s.parent_code
WHERE s.type='district'
ON DUPLICATE KEY UPDATE
  parent_id=VALUES(parent_id),
  name_ar=VALUES(name_ar),
  name_en=VALUES(name_en),
  is_active=1,
  metadata=VALUES(metadata),
  updated_at=NOW();

-- -------------------------------------------------------------------------
-- 5. Areas / shiyakhas / villages / local areas
-- -------------------------------------------------------------------------
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
SELECT
  p.id,
  'area',
  s.code,
  s.name_ar,
  s.name_en,
  'EG',
  1,
  JSON_OBJECT(
    'source','Open Admin Data',
    'source_code',s.code,
    'source_level','shiyakha',
    'food_van_level','area',
    'parent_source_code',s.parent_code,
    'dataset','open-admin-data/egypt-administrative-divisions',
    'license','CC-BY-4.0'
  ),
  NOW(),NOW()
FROM tmp_eg_food_van_geo s
JOIN geography_nodes p
  ON p.country_code='EG'
 AND p.type='district'
 AND p.code=s.parent_code
WHERE s.type='area'
ON DUPLICATE KEY UPDATE
  parent_id=VALUES(parent_id),
  name_ar=VALUES(name_ar),
  name_en=VALUES(name_en),
  is_active=1,
  metadata=VALUES(metadata),
  updated_at=NOW();

-- -------------------------------------------------------------------------
-- 6. FOOD Van service territory: all Egypt fallback
-- -------------------------------------------------------------------------
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,
 service_calendar,tags,capabilities,notes,created_at,updated_at)
VALUES
('EG-ALL','مصر - كل المناطق','Egypt - All Areas',@egypt_id,NULL,NULL,NULL,
 NULL,'active',100,NOW(),NULL,NULL,
 JSON_ARRAY('egypt','food-van','country'),
 JSON_OBJECT('van',true,'visits',true,'routing',true,'orders',true,'collections',true),
 'FOODEX FOOD Van country fallback territory. Hierarchy source: Open Admin Data CC-BY-4.0.',
 NOW(),NOW())
ON DUPLICATE KEY UPDATE
  name_ar=VALUES(name_ar),
  name_en=VALUES(name_en),
  country_node_id=VALUES(country_node_id),
  status='active',
  priority=VALUES(priority),
  tags=VALUES(tags),
  capabilities=VALUES(capabilities),
  notes=VALUES(notes),
  updated_at=NOW();

-- -------------------------------------------------------------------------
-- 7. FOOD Van service territory for every governorate
-- -------------------------------------------------------------------------
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,
 service_calendar,tags,capabilities,notes,created_at,updated_at)
SELECT
  CONCAT('EG-GOV-',g.code),
  g.name_ar,
  g.name_en,
  @egypt_id,
  g.id,
  NULL,
  NULL,
  NULL,
  'active',
  200,
  NOW(),
  NULL,
  NULL,
  JSON_ARRAY('egypt','food-van','governorate'),
  JSON_OBJECT('van',true,'visits',true,'routing',true,'orders',true,'collections',true),
  'FOODEX FOOD Van governorate territory. Hierarchy source: Open Admin Data CC-BY-4.0.',
  NOW(),NOW()
FROM geography_nodes g
WHERE g.country_code='EG'
  AND g.type='governorate'
  AND g.parent_id=@egypt_id
  AND g.is_active=1
ON DUPLICATE KEY UPDATE
  name_ar=VALUES(name_ar),
  name_en=VALUES(name_en),
  country_node_id=VALUES(country_node_id),
  governorate_node_id=VALUES(governorate_node_id),
  status='active',
  priority=VALUES(priority),
  tags=VALUES(tags),
  capabilities=VALUES(capabilities),
  notes=VALUES(notes),
  updated_at=NOW();

-- -------------------------------------------------------------------------
-- 8. FOOD Van service territory for every district / markaz / qism
-- This is the most granular territory level supported cleanly by the current
-- service_territories schema (district_node_id).
-- -------------------------------------------------------------------------
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,
 service_calendar,tags,capabilities,notes,created_at,updated_at)
SELECT
  CONCAT('EG-DIST-',d.code),
  d.name_ar,
  d.name_en,
  @egypt_id,
  g.id,
  NULL,
  d.id,
  NULL,
  'active',
  300,
  NOW(),
  NULL,
  NULL,
  JSON_ARRAY('egypt','food-van','district'),
  JSON_OBJECT('van',true,'visits',true,'routing',true,'orders',true,'collections',true),
  CONCAT('FOODEX FOOD Van district territory under ',g.name_en,'. Hierarchy source: Open Admin Data CC-BY-4.0.'),
  NOW(),NOW()
FROM geography_nodes d
JOIN geography_nodes g
  ON g.id=d.parent_id
 AND g.country_code='EG'
 AND g.type='governorate'
WHERE d.country_code='EG'
  AND d.type='district'
  AND d.is_active=1
ON DUPLICATE KEY UPDATE
  name_ar=VALUES(name_ar),
  name_en=VALUES(name_en),
  country_node_id=VALUES(country_node_id),
  governorate_node_id=VALUES(governorate_node_id),
  district_node_id=VALUES(district_node_id),
  status='active',
  priority=VALUES(priority),
  tags=VALUES(tags),
  capabilities=VALUES(capabilities),
  notes=VALUES(notes),
  updated_at=NOW();

DROP TEMPORARY TABLE IF EXISTS tmp_eg_food_van_geo;

COMMIT;

SET SQL_SAFE_UPDATES = @OLD_SQL_SAFE_UPDATES;

-- -------------------------------------------------------------------------
-- 9. Verification — expected:
-- country=1, governorate=27, district=365, area=5716
-- service territories=393 (1 country + 27 governorates + 365 districts)
-- -------------------------------------------------------------------------
SELECT type,COUNT(*) AS node_count
FROM geography_nodes
WHERE country_code='EG'
  AND is_active=1
GROUP BY type
ORDER BY FIELD(type,'country','governorate','district','area'),type;

SELECT COUNT(*) AS egypt_food_van_service_territories
FROM service_territories
WHERE code='EG-ALL'
   OR code LIKE 'EG-GOV-%'
   OR code LIKE 'EG-DIST-%';

-- Parent integrity check: expected orphan_count = 0
SELECT COUNT(*) AS orphan_count
FROM geography_nodes n
LEFT JOIN geography_nodes p ON p.id=n.parent_id
WHERE n.country_code='EG'
  AND n.type IN ('governorate','district','area')
  AND p.id IS NULL;

-- FOOD Van assignment-ready territory list
SELECT
  st.id,
  st.code AS territory_key,
  st.name_ar,
  st.name_en,
  st.status,
  st.priority,
  g.name_ar AS governorate_ar,
  g.name_en AS governorate_en,
  d.name_ar AS district_ar,
  d.name_en AS district_en
FROM service_territories st
LEFT JOIN geography_nodes g ON g.id=st.governorate_node_id
LEFT JOIN geography_nodes d ON d.id=st.district_node_id
WHERE st.code='EG-ALL'
   OR st.code LIKE 'EG-GOV-%'
   OR st.code LIKE 'EG-DIST-%'
ORDER BY st.priority,COALESCE(g.name_ar,''),COALESCE(d.name_ar,''),st.name_ar;
